Lemma fm12_0RB0LA_1LA1LC_0RD1LC_1RB1RD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  fm1_0RB0LA_1LA1LC_0RD1LC_1RB1RD r ph + fm2_0RB0LA_1LA1LC_0RD1LC_1RB1RD r ph
  + (length (f_pre (fam_fill FAM ph)) + length (f_suf (fam_fill FAM ph)))
  = r + f_s (fam_fill FAM ph).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
