Lemma farm_rhs_0RB0LA_1LC0RD_1LA1LC_1RC1RD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  lr_rhs (farm_0RB0LA_1LC0RD_1LA1LC_1RC1RD r ph)
    = cls_conf FAM (run_side FAM (f_mid (fam_fill FAM ph)) (fm1_0RB0LA_1LC0RD_1LA1LC_1RC1RD r ph)
                      (astride 1 1 r) (fm2_0RB0LA_1LC0RD_1LA1LC_1RC1RD r ph)
