(** ** What this board establishes

    8 of 10 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 10 of them
    collapse to 4 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 2 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)

(** *** The inner rules: what the nested arms iterate

    2 rule(s), validated like the ladder at both tails opaque. *)
Definition nlad_0RB0LA_1RC0RD_1LA1LC_1RB1RD : list (LRule * list rstep) :=
  [(mkLRule (mkC StB (mkS [S0] [] 0 0 []) S1 (mkS [S1;S1] [S1] 3 0 [S0;S0;S1])) (mkC StB (mkS [S0] [] 0 0 []) S1 (mkS [S1;S1] [S1] 3 3 [])) 6 12, [RB (SWin 2);RB (SCycR 1);RB (SWin 6);RB (SCycL 1 0);RB (SWin 4);RB (SRotR 1);RB (SRotR 1);RB (SRotR 1);RB (SFoldR 1);RB (SFoldR 2)]);
   (mkLRule (mkC StB (mkS [S0] [] 0 0 []) S1 (mkS [S1;S1] [S1] 3 0 [S0;S0;S1])) (mkC StB (mkS [S0] [] 0 0 []) S1 (mkS [S1;S1] [S1] 3 3 [])) 6 12, [RB (SWin 2);RB (SCycR 1);RB (SWin 6);RB (SCycL 1 0);RB (SWin 4);RB (SRotR 1);RB (SRotR 1);RB (SRotR 1);RB (SFoldR 1);RB (SFoldR 2)])].
Definition nrules_0RB0LA_1RC0RD_1LA1LC_1RB1RD : list LRule := map fst nlad_0RB0LA_1RC0RD_1LA1LC_1RB1RD.
Local Notation nrules := nrules_0RB0LA_1RC0RD_1LA1LC_1RB1RD.

Lemma nladder_ok_0RB0LA_1RC0RD_1LA1LC_1RB1RD : check_ladder tm [] nlad_0RB0LA_1RC0RD_1LA1LC_1RB1RD = true.
Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_0RB0LA_1RC0RD_1LA1LC_1RB1RD : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_0RB0LA_1RC0RD_1LA1LC_1RB1RD. Qed.

Definition iarm0_0_0RB0LA_1RC0RD_1LA1LC_1RB1RD : LRule :=
  mkLRule (mkC StD (mkS [S1;S1] [] 0 0 []) S0 (mkS [S0;S0;S0] [] 0 0 []))
          (mkC StD (mkS [S1;S1] [] 0 0 []) S0 (mkS [S0;S1;S0] [] 0 0 [])) 0 1.
