Definition iarm0_2_0RB0LA_1RC0RD_1LA1LC_1RB1RD : LRule :=
  mkLRule (mkC StD (mkS [S1;S1] [] 0 0 []) S0 (mkS [S0;S1;S0;S0;S1;S0] [S0;S1;S0] 1 0 [S0;S0;S0]))
          (mkC StD (mkS [S1;S1] [] 0 0 []) S0 (mkS [S0;S0;S0;S0;S0;S0] [S0;S0;S0] 1 0 [S0;S1;S0])) 0 1.
