   NCh [RB (SWin 2);RB (SCycR 1);RB (SWinR 6);RB (SCycL 1 0);RB (SWin 14);RB (SRotR 1);RB (SWin 1)]].
Lemma ok_farm1_0_0RB0LA_1RC0RD_1LA1LC_1RB1RD :
