(** 0RB0LA_1RC---_0LC1RD_1LA1RB *)
Definition tm_0RB0LA_1RC____0LC1RD_1LA1RB : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB
  | StA, S1 => mk S0 DL StA
  | StB, S0 => mk S1 DR StC
  | StB, S1 => None
  | StC, S0 => mk S0 DL StC
  | StC, S1 => mk S1 DR StD
  | StD, S0 => mk S1 DL StA
  | StD, S1 => mk S1 DR StB
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_0RB0LA_1RC____0LC1RD_1LA1RB : list Instr := [(StB, S1)].
Local Notation tm := (tm_wrap_trs tm_0RB0LA_1RC____0LC1RD_1LA1RB pins_0RB0LA_1RC____0LC1RD_1LA1RB).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_0RB0LA_1RC____0LC1RD_1LA1RB : Fam := mkFam 4 [[S0;S0;S0];[S0;S1;S0];[S0;S0;S1];[S0;S1;S1]] [] [[]] Binary 1 [mkFill 1 [] 0 [1] 0] StA S0 false [].
Local Notation FAM := fam_0RB0LA_1RC____0LC1RD_1LA1RB.

(** ** The ladder, as DATA

    2 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_0RB0LA_1RC____0LC1RD_1LA1RB : list (LRule * list rstep) :=
  [(mkLRule (mkC StA (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StA (mkS [] [] 0 0 []) S1 (mkS [S0] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S1;S0;S1] [] 0 0 [])) (mkC StC (mkS [S1;S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 3, [RB (SWin 3)])].
Local Notation lad := lad_0RB0LA_1RC____0LC1RD_1LA1RB.

Definition rules_0RB0LA_1RC____0LC1RD_1LA1RB : list LRule := map fst lad.
Local Notation rules := rules_0RB0LA_1RC____0LC1RD_1LA1RB.

Lemma ladder_ok_0RB0LA_1RC____0LC1RD_1LA1RB : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_0RB0LA_1RC____0LC1RD_1LA1RB : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_0RB0LA_1RC____0LC1RD_1LA1RB. Qed.

