Definition iarm_0RB0LA_1RC____0LC1RD_1LA1RB (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_0RB0LA_1RC____0LC1RD_1LA1RB
  | 1, 0 => iarm1_0_0RB0LA_1RC____0LC1RD_1LA1RB
  | 2, 0 => iarm2_0_0RB0LA_1RC____0LC1RD_1LA1RB
  | _, _ => iarm0_0_0RB0LA_1RC____0LC1RD_1LA1RB   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

