              | Some c => ceqb c (fam_cfg FAM ([0], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 15 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_0RB0LC_1LC1RB_1LA0RD_1RC0LA : NeverQuasiHaltsTr tm_0RB0LC_1LC1RB_1LA0RD_1RC0LA.
Proof.
  eapply (boardN_neverqhtr tm_0RB0LC_1LC1RB_1LA0RD_1RC0LA pins_0RB0LC_1LC1RB_1LA0RD_1RC0LA FAM 1
                           iarm_0RB0LC_1LC1RB_1LA0RD_1RC0LA 1 1
                           farm_0RB0LC_1LC1RB_1LA0RD_1RC0LA 1 1
                           fm1_0RB0LC_1LC1RB_1LA0RD_1RC0LA fm2_0RB0LC_1LC1RB_1LA0RD_1RC0LA 0
                           nrules vsegs_0RB0LC_1LC1RB_1LA0RD_1RC0LA vis_0RB0LC_1LC1RB_1LA0RD_1RC0LA
                           [0] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
