  [(mkLRule (mkC StD (mkS [] [S0;S1] 1 0 [S0;S1;S1]) S1 (mkS [] [] 0 0 [])) (mkC StD (mkS [] [S0;S1] 1 1 [S0]) S1 (mkS [] [] 0 0 [])) 4 6, [RB (SRotL 1);RB (SWin 1);RB (SCycL 2 0);RB (SWin 4);RB (SCycR 2);RB (SWin 1);RB (SRotL 1);RB (SFoldL 1)]);
   (mkLRule (mkC StD (mkS [S0;S1] [S0;S1] 1 0 [S1;S1]) S1 (mkS [] [] 0 0 [])) (mkC StD (mkS [S0;S1] [S0;S1] 1 1 []) S1 (mkS [] [] 0 0 [])) 4 6, [RB (SWin 2);RB (SCycL 2 0);RB (SWin 2);RB (SCycR 2);RB (SWin 2);RB (SRotL 2);RB (SFoldL 1)])].
Definition nrules_0RB0LC_1LC1RB_1LA0RD_1RC1LC : list LRule := map fst nlad_0RB0LC_1LC1RB_1LA0RD_1RC1LC.
Local Notation nrules := nrules_0RB0LC_1LC1RB_1LA0RD_1RC1LC.

