(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_0RB0LD_1RC0LA_1LD1RB____1LA : NeverQuasiHaltsTr tm_0RB0LD_1RC0LA_1LD1RB____1LA.
Proof.
  apply (boardph_neverqhtr tm_0RB0LD_1RC0LA_1LD1RB____1LA pins_0RB0LD_1RC0LA_1LD1RB____1LA FAM 1
                           iarm_0RB0LD_1RC0LA_1LD1RB____1LA 1 1
                           farm_0RB0LD_1RC0LA_1LD1RB____1LA 1 1
                           fm1_0RB0LD_1RC0LA_1LD1RB____1LA fm2_0RB0LD_1RC0LA_1LD1RB____1LA 0 vis_0RB0LD_1RC0LA_1LD1RB____1LA
                           [2] 0 4).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
