Local Notation tm := (tm_wrap_trs tm_0RB0LD_1RC1RB_0LA0RC_1LB1LD pins_0RB0LD_1RC1RB_0LA0RC_1LB1LD).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_0RB0LD_1RC1RB_0LA0RC_1LB1LD : Fam := mkFam 2 [[S0;S0];[S1;S0]] [] [[S1]] Binary 1 [mkFill 1 [] 0 [] 0] StA S0 true [].
Local Notation FAM := fam_0RB0LD_1RC1RB_0LA0RC_1LB1LD.

(** ** The ladder, as DATA

    3 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_0RB0LD_1RC1RB_0LA0RC_1LB1LD : list (LRule * list rstep) :=
  [(mkLRule (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StC (mkS [S0] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StB (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StD (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)])].
Local Notation lad := lad_0RB0LD_1RC1RB_0LA0RC_1LB1LD.

Definition rules_0RB0LD_1RC1RB_0LA0RC_1LB1LD : list LRule := map fst lad.
Local Notation rules := rules_0RB0LD_1RC1RB_0LA0RC_1LB1LD.

Lemma ladder_ok_0RB0LD_1RC1RB_0LA0RC_1LB1LD : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_0RB0LD_1RC1RB_0LA0RC_1LB1LD : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_0RB0LD_1RC1RB_0LA0RC_1LB1LD. Qed.

