  mkLRule (mkC StD (mkS [] [S1;S1;S1] 1 0 [S0;S0;S0]) S1 (mkS [] [] 0 0 []))
          (mkC StD (mkS [] [S0;S0;S0] 1 0 [S1;S1;S0]) S1 (mkS [] [] 0 0 [])) 0 1.
Definition ch_iarm0_0_0RB0RA_0LC1LD_0LD1LB_1RA1LC : list nseg :=
  [NCh [RB (SCycL 3 0);RB (SWin 6);RB (SCycR 3);RB (SWinR 8)]].
