  | 1, (StD, S1) => [SWinR 18]
  | 2, (StA, S0) => [SWin 0]
  | 2, (StA, S1) => [SWinR 3]
  | 2, (StB, S0) => [SWinR 2]
  | 2, (StB, S1) => [SWin 1]
  | 2, (StC, S0) => [SWinR 7]
  | 2, (StC, S1) => [SWinR 4]
  | 2, (StD, S0) => [SWinR 5]
  | 2, (StD, S1) => [SWinR 9]
