  | 2, (StC, S1) => [NCh [RB (SWin 1)]; NUp 2 [] [S1] 0 1 0 (mkS [S0] [] 0 0 []) (mkS [] [] 0 0 []) false]
  | 2, (StD, S0) => [NCh [RB (SWin 1)]; NUp 2 [] [S1] 0 1 0 (mkS [S0] [] 0 0 []) (mkS [] [] 0 0 []) false]
  | 2, (StD, S1) => [NCh [RB (SWin 1)]; NUp 2 [] [S1] 0 1 0 (mkS [S0] [] 0 0 []) (mkS [] [] 0 0 []) false]
  | _, _ => []
  end.

