(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_0RB0RC_1LA1RB_1RC1LD_0LA0LD : NeverQuasiHaltsTr tm_0RB0RC_1LA1RB_1RC1LD_0LA0LD.
Proof.
  eapply (boardN_neverqhtr tm_0RB0RC_1LA1RB_1RC1LD_0LA0LD pins_0RB0RC_1LA1RB_1RC1LD_0LA0LD FAM 1
                           iarm_0RB0RC_1LA1RB_1RC1LD_0LA0LD 2 1
