  ph < 1 ->
  ReachL tm true true (lr_lhs (farm_0RB1LA_1LA1RC_1LD1RB_0RC0LD r ph)) (lr_rhs (farm_0RB1LA_1LA1RC_1LD1RB_0RC0LD r ph)).
