Lemma farm_rhs_0RB1LA_1LA1RC_1LD1RB_0RC0LD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  lr_rhs (farm_0RB1LA_1LA1RC_1LD1RB_0RC0LD r ph)
    = cls_conf FAM (run_side FAM (f_mid (fam_fill FAM ph)) (fm1_0RB1LA_1LA1RC_1LD1RB_0RC0LD r ph)
                      (astride 1 1 r) (fm2_0RB1LA_1LA1RC_1LD1RB_0RC0LD r ph)
                      (f_to (fam_fill FAM ph))
                      (f_pre (fam_fill FAM ph)) (f_suf (fam_fill FAM ph))).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
  {
    destruct ph as [|ph].
